#!/bin/bash

# update-amalgamation.sh replaces the libvsql C in internal/amalgamation with
# the C from a vsql amalgamation (vsql-VERSION-amalgamation.zip from a vsql
# release, or the folder it unzips to). With no arguments, or a version, the zip
# is downloaded from the latest (or that) vsql release:
#
#   scripts/update-amalgamation.sh
#   scripts/update-amalgamation.sh v1.2.3
#   scripts/update-amalgamation.sh vsql-v1.2.3-amalgamation.zip
#
# Only what's needed to compile libvsql is copied: libvsql.c (which has all of
# libvsql's C, including the garbage collector, for every OS and architecture),
# libvsql.h and the licenses. vsql/cgo_flags.go is generated from the libraries
# in vsql.mk, which are the ones that V used to link libvsql on each OS and
# architecture.
#
# internal/amalgamation isn't a Go package, since cgo would compile each .c file
# in it on its own. Instead, libvsql.c in the vsql package includes the one in
# internal/amalgamation.

set -euo pipefail

source="${1:-latest}"
root="$(cd "$(dirname "$0")/.." && pwd)"
out="$root/internal/amalgamation"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

if [ ! -e "$source" ]; then
  version="$source"
  if [ "$version" = latest ]; then
    version="$(curl -fsSL https://api.github.com/repos/elliotchance/vsql/releases/latest |
      sed -n 's/^ *"tag_name": *"\(.*\)",$/\1/p')"
  fi
  zip="vsql-$version-amalgamation.zip"
  echo "Downloading $zip"
  curl -fsSL -o "$tmp/$zip" \
    "https://github.com/elliotchance/vsql/releases/download/$version/$zip"
  source="$tmp/$zip"
fi

if [ -f "$source" ]; then
  unzip -q "$source" -d "$tmp/unzipped"
  source="$(dirname "$(find "$tmp/unzipped" -name libvsql.h | head -1)")"
fi

if [ ! -f "$source/libvsql.h" ] || [ ! -f "$source/libvsql.c" ] || [ ! -f "$source/vsql.mk" ]; then
  echo "$1 isn't a vsql amalgamation (there's no libvsql.h, libvsql.c or vsql.mk)" >&2
  exit 1
fi

rm -rf "$out"
mkdir -p "$out"
for name in libvsql.c libvsql.h LICENSE LICENSE-V; do
  cp "$source/$name" "$out/"
done

# The #cgo lines for each OS and architecture in vsql.mk. libvsql.c defines
# everything it needs itself, so there are only libraries.
flags="$root/vsql/cgo_flags.go"
{
  echo "// Code generated by scripts/update-amalgamation.sh. DO NOT EDIT."
  echo
  echo "package vsql"
  echo
  echo "// The libraries that V used to link libvsql, from the vsql.mk file of the"
  echo "// amalgamation."
  echo
  sed -n 's/^ifeq (\$(VSQL_OS)_\$(VSQL_ARCH),\(.*\))$/\1/p' "$source/vsql.mk" |
    while read -r os_arch; do
      os="${os_arch%_*}"
      arch="${os_arch#*_}"
      if [ "$os" = macos ]; then
        os=darwin
      fi

      cflags=""
      ldflags=""
      for arg in $(sed -n "/^ifeq (\$(VSQL_OS)_\$(VSQL_ARCH),$os_arch)$/,/^endif$/s/^LIBVSQL_FLAGS *= *//p" "$source/vsql.mk"); do
        case "$arg" in
          # Options for linking libvsql as a shared library.
          -Wl,*) ;;
          -D*) cflags="$cflags $arg" ;;
          *) ldflags="$ldflags $arg" ;;
        esac
      done
      if [ -n "$cflags" ]; then
        echo "// #cgo $os,$arch CFLAGS:$cflags"
      fi
      if [ -n "$ldflags" ]; then
        echo "// #cgo $os,$arch LDFLAGS:$ldflags"
      fi
    done
  echo "import \"C\""
} > "$flags"
gofmt -l "$flags" > /dev/null

echo "Updated $out and $flags from ${1:-the latest release}"
